    return db.fetch_all("SELECT * FROM refunds")

def login(db, email, password):
    user = db.fetch_one("SELECT * FROM users WHERE email = %s", (email,))
    if user and verify_password(password, user['salt'], user['hash']):
        return create_session(db, user['id'])

def cancel_order(db, user, order_id):
    order = get_order(db, user, order_id)
    change_status(db, order, 'cancelled')

def notify_shipped(order):
    body = render_template(SHIPPED_TEMPLATE, order)
    send_email(order['email'], 'Your order has shipped', body)

def replace_product_image(filename, data):
    path = UPLOAD_ROOT / filename
    path.write_bytes(data)

